:root {
  color-scheme: dark;
  --indicator-panel-height: 112px;
  font-family: "Trebuchet MS", "DejaVu Sans", Arial, sans-serif;
  background: #16130f;
  color: #f1eadf;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  background: #16130f;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
}

#app {
  position: fixed;
  left: 50%;
  top: 50%;
  width: 1280px;
  height: 720px;
  background: #111;
  transform-origin: center center;
  transform: translate(-50%, -50%) scale(var(--app-scale, 1));
}

#game {
  display: block;
  width: 1280px;
  height: 720px;
  image-rendering: auto;
}

#ui-root {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

button {
  font: inherit;
  min-height: 38px;
  border: 1px solid #a78b5c;
  background: #34291d;
  color: #f5ead5;
  cursor: pointer;
}

button:hover {
  background: #4a3825;
}

button.active {
  background: #4a3825;
  box-shadow: inset 0 0 9px rgba(230, 190, 91, 0.24), 0 0 8px rgba(196, 163, 76, 0.2);
}

.top-bar {
  position: absolute;
  top: 14px;
  left: 14px;
  right: 14px;
  display: flex;
  justify-content: space-between;
  gap: 6px;
  pointer-events: auto;
}

.top-bar-left,
.top-bar-right {
  display: flex;
  gap: 6px;
}

.top-bar button {
  min-width: 58px;
  padding: 0 10px;
}

.game-hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  color: #f5ead5;
}

.hud-meters,
.hud-verb,
.inventory-dock-panel {
  position: absolute;
  border: 1px solid rgba(177, 146, 94, 0.42);
  background: linear-gradient(180deg, rgba(40, 32, 23, 0.84), rgba(20, 17, 13, 0.76));
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.32), inset 0 1px rgba(255, 244, 216, 0.08);
  backdrop-filter: blur(5px) saturate(0.85);
}

.hud-meters {
  left: 18px;
  bottom: 18px;
  width: 292px;
  height: var(--indicator-panel-height);
  display: grid;
  gap: 8px;
  padding: 11px 13px;
  border-radius: 11px;
}

.hud-meter {
  display: grid;
  grid-template-columns: 128px 1fr;
  align-items: center;
  gap: 9px;
  min-height: 16px;
}

.hud-meter-label {
  overflow: hidden;
  color: #eee3d1;
  font-size: 13px;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hud-meter-track {
  height: 11px;
  overflow: hidden;
  border: 1px solid rgba(190, 163, 118, 0.65);
  border-radius: 999px;
  background: rgba(15, 13, 10, 0.72);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.6);
}

.hud-meter-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #69b6ff;
  box-shadow: 0 0 8px rgba(105, 182, 255, 0.42);
}

.hud-meter.suspicion .hud-meter-fill {
  background: #e36767;
  box-shadow: 0 0 8px rgba(227, 103, 103, 0.38);
}

.hud-meter.public-mood .hud-meter-fill {
  background: #8ccf73;
  box-shadow: 0 0 8px rgba(140, 207, 115, 0.4);
}

.hud-meter.intoxication .hud-meter-track {
  position: relative;
}

.hud-meter.intoxication .hud-meter-fill {
  transition: width 180ms ease, background 180ms ease;
}

.hud-meter-glass {
  position: absolute;
  inset: 0;
  color: #fff5dd;
  font-size: 10px;
  font-weight: 700;
  line-height: 11px;
  text-align: center;
  text-shadow: 0 1px 2px #120e09;
}

.hud-verb {
  left: 50%;
  bottom: 20px;
  display: block;
  min-height: 38px;
  min-width: 112px;
  padding: 8px 18px;
  border-radius: 999px;
  color: #fff2d8;
  font-size: 17px;
  font-weight: 600;
  transform: translateX(-50%);
  white-space: nowrap;
  pointer-events: auto;
}

.hud-verb:hover,
.hud-verb:focus-visible {
  border-color: rgba(231, 192, 121, 0.82);
  background: linear-gradient(180deg, rgba(62, 48, 31, 0.94), rgba(28, 22, 15, 0.9));
  color: #fff2d8;
  outline: none;
}

.inventory-dock-panel {
  right: 18px;
  bottom: 14px;
  width: max-content;
  max-width: 760px;
  padding: 8px;
  overflow: visible;
  border-radius: 18px;
  pointer-events: auto;
}

.inventory-dock {
  display: flex;
  flex-wrap: wrap-reverse;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 8px;
  max-width: 742px;
}

.inventory-item {
  position: relative;
  flex: 0 0 78px;
  width: 78px;
  height: 78px;
  min-height: 78px;
  padding: 0;
  border: 1px solid rgba(200, 169, 113, 0.58);
  border-radius: 15px;
  background: radial-gradient(circle at 50% 32%, rgba(255, 245, 216, 0.14), rgba(43, 34, 24, 0.82));
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.38), inset 0 1px rgba(255, 249, 228, 0.12);
  transform-origin: 50% 100%;
  transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1), border-color 160ms ease,
    filter 160ms ease, box-shadow 160ms ease;
  cursor: pointer;
}

.inventory-item img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 5px 5px rgba(0, 0, 0, 0.38));
