}

.inventory-item-label {
  display: block;
  padding: 5px;
  color: #fff0d0;
  font-size: 12px;
  line-height: 1.2;
  overflow-wrap: anywhere;
  pointer-events: none;
}

.inventory-item:hover,
.inventory-item:focus-visible,
.inventory-item.selected,
.inventory-item.using {
  z-index: 3;
  border-color: rgba(246, 208, 137, 0.95);
  background: radial-gradient(circle at 50% 28%, rgba(255, 247, 217, 0.24), rgba(55, 42, 27, 0.94));
  box-shadow: 0 13px 23px rgba(0, 0, 0, 0.46), 0 0 0 2px rgba(222, 181, 106, 0.28);
  filter: saturate(1.08) brightness(1.06);
  outline: none;
  transform: translateY(-13px) scale(1.28);
}

.inventory-item:has(+ .inventory-item:hover),
.inventory-item:has(+ .inventory-item:focus-visible),
.inventory-item:hover + .inventory-item,
.inventory-item:focus-visible + .inventory-item {
  z-index: 2;
  transform: translateY(-5px) scale(1.1);
}

.inventory-tooltip {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  z-index: 5;
  max-width: 190px;
  padding: 6px 9px;
  border: 1px solid rgba(190, 153, 94, 0.7);
  border-radius: 7px;
  background: rgba(28, 22, 16, 0.96);
  color: #fff0d0;
  font-size: 13px;
  line-height: 1.2;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 5px) scale(0.8);
  transition: opacity 120ms ease, transform 150ms ease;
  white-space: nowrap;
}

.inventory-item:hover .inventory-tooltip,
.inventory-item:focus-visible .inventory-tooltip {
  opacity: 1;
  transform: translate(-50%, 0) scale(0.78);
}

.inventory-item-actions {
  display: grid;
  grid-template-columns: minmax(120px, 1fr) repeat(4, auto);
  align-items: center;
  gap: 7px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(190, 153, 94, 0.42);
}

.inventory-item-actions-name {
  overflow: hidden;
  color: #fff0d0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.inventory-item-actions button {
  min-height: 34px;
  padding: 6px 10px;
}

.inventory-use-indicator {
  position: absolute;
  left: 50%;
  bottom: 72px;
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: 520px;
  padding: 8px 10px 8px 14px;
  border: 1px solid rgba(231, 192, 121, 0.82);
  border-radius: 999px;
  background: rgba(30, 23, 16, 0.94);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.42), 0 0 12px rgba(222, 181, 106, 0.2);
  color: #fff0d0;
  transform: translateX(-50%);
  pointer-events: auto;
}

.inventory-use-instruction {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.inventory-use-indicator button {
  min-height: 32px;
  padding: 5px 10px;
  border-radius: 999px;
}

.dropped-items-panel {
  left: 50%;
  bottom: 132px;
  width: min(430px, calc(100vw - 28px));
  padding: 16px;
  transform: translateX(-50%);
}

.dropped-items-panel h2 {
