}

.dropped-item-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .inventory-item,
  .inventory-tooltip {
    transition-duration: 1ms;
  }

  .inventory-item:hover,
  .inventory-item:focus-visible,
  .inventory-item:has(+ .inventory-item:hover),
  .inventory-item:has(+ .inventory-item:focus-visible),
  .inventory-item:hover + .inventory-item,
  .inventory-item:focus-visible + .inventory-item {
    transform: none;
  }
}

.panel {
  position: absolute;
  pointer-events: auto;
  background: rgba(26, 22, 17, 0.96);
  border: 1px solid #96784f;
