.dialogue-speech-bubble {
  --dialogue-bubble-bg: rgba(255, 245, 211, 0.96);
  --dialogue-bubble-ink: #493523;
  --dialogue-bubble-accent: #b96d35;
  position: absolute;
  z-index: 4;
  width: max-content;
