  transform: translate(-50%, -100%) rotate(-0.4deg);
  pointer-events: none;
}

.dialogue-speech-bubble::before,
.dialogue-speech-bubble::after {
  position: absolute;
  left: calc(50% + var(--dialogue-tail-offset));
  content: "";
  transform: translateX(-50%);
}

.dialogue-speech-bubble::before {
  bottom: -25px;
  border: 13px solid transparent;
  border-top: 24px solid var(--dialogue-bubble-accent);
  border-bottom: 0;
}

.dialogue-speech-bubble::after {
  bottom: -18px;
