}

.dialogue-speech-bubble.speaker-npc-municipality_clerk {
  --dialogue-bubble-bg: rgba(240, 235, 211, 0.97);
  --dialogue-bubble-ink: #3f392a;
  --dialogue-bubble-accent: #76705b;
  border-radius: 11px;
}

.npc-reaction-bubble.phase-in {
  animation: speech-fade-in 300ms ease-out both;
}

.npc-reaction-bubble.phase-out {
  animation: speech-fade-out 300ms ease-in both;
}

.speech-bubble {
  position: absolute;
  min-width: 200px;
  max-height: 190px;
  /*transform: translate(-50%, -100%);*/
  pointer-events: none;
  color: #4b3625;
  filter: drop-shadow(0 14px 22px rgba(0, 0, 0, 0.34));
  opacity: 1;
  box-sizing: border-box;
}

.speech-bubble.beat-resizing {
  transition: width 400ms ease-in-out, height 400ms ease-in-out, left 400ms ease-in-out,
    right 400ms ease-in-out, bottom 400ms ease-in-out;
}

.speech-bubble.phase-beat-out .speech-text {
  animation: speech-text-out 200ms ease-in both;
}

.speech-bubble.phase-beat-in .speech-text {
  animation: speech-text-in 200ms ease-out both;
}

.speech-bubble.phase-in {
  animation: speech-fade-in 300ms ease-out both;
}

.speech-bubble.phase-out {
  animation: speech-fade-out 300ms ease-in both;
}

.speech-blobs {
  position: relative;
  z-index: 1;
  max-height: inherit;
  padding: 12px 16px;
  overflow: visible;
  filter: url("#speech-goo");
  box-sizing: border-box;
  height: 100%;
}

.speech-blob-top,
.speech-blob-bottom {
  position: absolute;
  left: 0;
  right: 0;
  z-index: 0;
  background: #fff4cf;
}

.speech-blob-top {
  top: 0;
  height: 78%;
  border-radius: 42% 44% 32% 36% / 130% 125% 95% 110%;
  animation: speech-blob 1.7s cubic-bezier(0.37, 0, 0.63, 1) infinite alternate;
}

.speech-blob-bottom {
  left: 4%;
  right: 4%;
  bottom: 0;
  height: 45%;
  border-radius: 16% 12% 28% 24% / 80% 90% 130% 120%;
  animation: speech-blob 1.25s cubic-bezier(0.37, 0, 0.63, 1) 120ms infinite alternate-reverse;
}

.speech-text {
  position: relative;
  z-index: 2;
  max-height: 150px;
  overflow: visible;
  padding: 0 12px;
  color: #5e513e;
  font-size: 20px;
  line-height: 1.32;
  font-weight: 400;
  overflow-wrap: anywhere;
  text-align: center;
}

.speech-text-measure {
  position: absolute;
  left: -10000px;
  top: -10000px;
  visibility: hidden;
  box-sizing: border-box;
  max-height: none;
  pointer-events: none;
}

.speech-measure {
  position: absolute;
  left: -10000px;
  top: -10000px;
  visibility: hidden;
  filter: none;
}

.speech-measure .speech-tail {
  display: none;
}

.speech-speaker {
  position: absolute;
  left: 22px;
  top: -19px;
  z-index: 2;
  padding: 5px 16px 6px;
  border-radius: 45% 36% 42% 34% / 100% 80% 100% 90%;
  background: #d48638;
  color: #2c1711;
  font-weight: 400;
  font-size: 15px;
  letter-spacing: 1px;
  transform: rotate(-4deg);
  box-shadow: 0 3px 0 rgba(96, 45, 22, 0.22);
  animation: speech-speaker-float 1.45s cubic-bezier(0.37, 0, 0.63, 1) 80ms infinite alternate;
}

.speech-tail {
  position: absolute;
  z-index: 0;
  bottom: -56px;
  width: 132px;
  height: 82px;
  overflow: visible;
  animation: speech-tail 1.35s cubic-bezier(0.37, 0, 0.63, 1) 0.2s infinite alternate;
}

.speech-tail path {
  fill: #fff4cf;
}

.speech-bubble.tail-left .speech-tail {
  left: 56px;
  bottom: -32px;
  transform-origin: 100% 0;
  transform: rotate(-10deg);
}

.speech-bubble.tail-right .speech-tail {
  right: -76px;
  transform-origin: 0 0;
  transform: scaleX(-1) rotate(-10deg);
}

.speech-bubble.reject .speech-blob-top,
.speech-bubble.reject .speech-blob-bottom,
.speech-bubble.reject .speech-tail path {
  background: #ffe1c8;
  fill: #ffe1c8;
}

.speech-bubble.reject .speech-speaker {
  background: #c65f3f;
  color: #fbe8cf;
}

@keyframes speech-blob {
  from {
    transform: rotate(0.45deg) scale(1.006);
  }
  to {
    transform: rotate(-0.45deg) scale(0.985);
  }
}

@keyframes speech-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes speech-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes speech-text-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes speech-text-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes speech-tail {
  from {
    margin-bottom: 0;
  }
  to {
    margin-bottom: 5.5px;
  }
}

@keyframes speech-speaker-float {
  from {
    margin-top: 0;
  }
  to {
    margin-top: 4px;
  }
}

.dev-home {
  left: 50%;
  top: 50%;
  width: min(760px, calc(100% - 32px));
  max-height: calc(100% - 32px);
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  scrollbar-color: #96784f rgba(17, 14, 10, 0.65);
  scrollbar-width: thin;
  transform: translate(-50%, -50%);
  padding: 28px;
  display: grid;
  gap: 16px;
}

.dev-home h1,
.dev-home h2,
.dev-home p {
  margin: 0;
}

.dev-scene-editors a {
  font-weight: 700;
}

.dev-home a {
  pointer-events: auto;
  color: #f5ead5;
  text-decoration: none;
}

.play-link {
  display: block;
  padding: 18px 20px;
  background: #7a2f24;
  border: 1px solid #d8b46f;
  text-align: center;
  font-size: 28px;
  font-weight: 700;
}

.dev-links {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.dev-links a {
  padding: 10px;
  border: 1px solid rgba(216, 180, 111, 0.6);
  background: rgba(255, 255, 255, 0.06);
}

.dev-status-list {
  display: grid;
  gap: 8px;
}

.dev-status {
  display: grid;
  gap: 4px;
  padding: 10px;
  border: 1px solid rgba(216, 180, 111, 0.35);
  background: rgba(255, 255, 255, 0.05);
  line-height: 1.35;
}

.dev-status.pending {
  border-color: rgba(230, 190, 98, 0.65);
}

.dev-status.rejected {
  border-color: rgba(210, 100, 82, 0.7);
}

.dev-status span {
  color: #d8ccbb;
}

.dev-status code,
.dev-command {
  font-family: Consolas, "Courier New", monospace;
  color: #f2e5cf;
}

.dev-command {
  margin: 0;
  padding: 12px;
  overflow: auto;
  border: 1px solid rgba(216, 180, 111, 0.4);
  background: rgba(0, 0, 0, 0.28);
  white-space: pre-wrap;
}

.simple-anim-controls {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 18px;
  pointer-events: auto;
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(35, 31, 25, 0.45);
  background: rgba(24, 21, 18, 0.88);
  color: #f5ead5;
}

.simple-anim-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.simple-anim-controls button {
  min-height: 34px;
  padding: 0 10px;
}

.simple-anim-controls button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.simple-anim-controls label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
}

.simple-anim-controls input[type="range"] {
  width: min(360px, 45vw);
}

.scene-editor {
  left: 14px;
  top: 14px;
  width: min(360px, calc(100vw - 28px));
  padding: 12px;
  display: grid;
  gap: 8px;
  pointer-events: auto;
  background: rgba(20, 18, 14, 0.9);
  max-height: calc(100% - 28px);
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  scrollbar-color: #96784f rgba(17, 14, 10, 0.65);
  scrollbar-width: thin;
}

.scene-editor.right {
  left: auto;
  right: 14px;
}

.scene-editor-title {
  font-weight: 700;
}

.scene-editor-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.scene-editor-header button {
  min-height: 30px;
  padding: 4px 9px;
  white-space: nowrap;
}

.scene-editor label {
  display: grid;
  gap: 4px;
  font-size: 12px;
  color: #d9cbb5;
}

.scene-editor select,
.scene-editor input {
  min-height: 32px;
  border: 1px solid #a78b5c;
  background: #221b13;
  color: #f5ead5;
  padding: 0 5px;
}

.scene-editor-layer-position,
.scene-editor-raster-position {
  color: #d9f7ff;
  font-size: 12px;
  line-height: 1.35;
}

.scene-editor-layer-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.scene-editor-layer-grid input,
.scene-editor-action-grid input {
  max-width: 81px;
}

.scene-editor-action-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.scene-editor textarea {
  min-height: 112px;
  max-height: 220px;
  resize: vertical;
  border: 1px solid #a78b5c;
  background: #221b13;
  color: #f5ead5;
  padding: 6px;
  font-family: Consolas, "Liberation Mono", monospace;
  font-size: 12px;
}

.scene-editor-action-note {
  color: #d9f7ff;
  font-size: 12px;
  line-height: 1.35;
}

.scene-editor-actions {
  display: flex;
  gap: 8px;
}

.scene-editor-actions button {
  flex: 1;
  min-height: 32px;
}

.scene-editor-help,
.scene-editor-status {
  font-size: 12px;
  line-height: 1.35;
}

.scene-editor-status {
  color: #f0d38e;
}

/* Keep the creditor pair and the room visible beside the final record. */
.ending-panel {
  left: auto;
  right: 24px;
  width: 570px;
  padding: 24px;
  transform: translateY(-50%);
  border-top: 5px solid #b99b56;
}
.ending-panel[data-ending-id$="loss"] { border-top-color: #a76857; }
.ending-panel h1 { font-size: 28px; }
.ending-body { font-size: 16px; line-height: 1.4; }
.ending-results { margin: 14px 0; }
.ending-results div { padding: 8px; }
.ending-report { padding-left: 20px; font-size: 14px; line-height: 1.4; color: #e2d7c5; }
.ending-report li + li { margin-top: 5px; }
.ending-epilogue { margin: 14px 0 !important; padding: 12px; border-left: 3px solid #b99b56; background: #29241c; line-height: 1.45; }
.ending-languages { display: flex; gap: 6px; margin-top: 10px; }
.ending-languages button { padding: 4px 10px; font-size: 13px; }
.sound-volume { display: flex; align-items: center; gap: 12px; margin: 12px 0 18px; }
.sound-volume input { flex: 1; min-width: 80px; accent-color: #d9b86e; }
.sound-volume output { min-width: 4ch; text-align: right; }

/* Inline dialogue text must not push the scrollable choices below a clipped box. */
.dialogue-panel-with-line:not(.dialogue-panel-with-entries) {
  display: flex;
  flex-direction: column;
  height: auto;
  max-height: 45%;
  gap: 6px;
}
.dialogue-panel-with-line:not(.dialogue-panel-with-entries) > p {
  flex: 0 1 auto;
  min-height: 0;
  max-height: 130px;
  overflow-y: auto;
}
.dialogue-panel-with-line:not(.dialogue-panel-with-entries) .dialogue-choice-list {
  flex: 0 1 auto;
  min-height: 32px;
  height: auto;
  max-height: 150px;
  grid-auto-rows: minmax(30px, auto);
  scrollbar-gutter: stable;
}
.dialogue-panel-with-line .dialogue-choice-list button { white-space: normal; overflow-wrap: anywhere; }

.received-item-screen { position:absolute; inset:0; z-index:500; background:radial-gradient(ellipse at 50% 38%,#3b2d20,#1d1712 72%); color:#f6e7c8; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:10px; pointer-events:auto; text-align:center; padding:20px; overflow-y:auto; }
.received-item-screen h2 { font-size:16px; text-transform:uppercase; letter-spacing:3px; color:#ccb28a; margin:0; }
.received-item-screen h3 { font-size:30px; font-weight:500; margin:0; }
.received-item-screen p { max-width:620px; font-size:18px; margin:6px 0; color:#dbc7a8; }
.received-item-screen > button { padding:12px 36px; font-size:20px; margin-top:5px; }
.item-model-viewer { width:min(520px,85vw); height:clamp(270px,63vh,510px); position:relative; flex-shrink:0; }
.item-model-viewer-document { width:min(900px,90vw); height:clamp(270px,63vh,510px); }
.received-item-screen .item-model-help { margin:0; font-size:14px; }
.item-model-viewer canvas { width:100%; height:100%; display:block; touch-action:none; cursor:grab; }
