.item-model-viewer canvas:focus-visible { outline:2px solid #e1c48c; outline-offset:2px; }
.item-model-viewer img { height:100%; width:100%; object-fit:contain; }
.item-model-status { position:absolute; inset:45% 0 auto; }
.received-item-screen small { font-size:14px; color:#bfa886; }
@media (max-height:550px) { .received-item-screen { justify-content:flex-start; } .received-item-screen h3 { font-size:23px; } }
:root { --photo-puzzle-bg: #30251a; }
.photo-puzzle-screen { position:absolute; inset:1%; z-index:1000; overflow:auto; background:var(--photo-puzzle-bg); color:#f1dfba; border:2px solid #a88448; border-radius:12px; padding:12px 20px; display:flex; flex-direction:column; align-items:center; box-shadow:0 0 0 100vmax #000a; pointer-events:auto; }
