.photo-puzzle-controls,.photo-puzzle-pieces { display:flex; justify-content:center; gap:5px; flex-wrap:wrap; margin:4px; }
.photo-puzzle-screen button { padding:6px 10px; cursor:pointer; }
.photo-puzzle-pieces button { font-size:12px; }
.photo-puzzle-pieces button[aria-pressed=true] { outline:3px solid #edc16b; background:#6b4c23; }

